shell_commands.command:
patch -p1 <<'PATCH'
--- a/tests/src/unit-udt.cpp
+++ b/tests/src/unit-udt.cpp
@@ -19,6 +19,8 @@
 #endif

+#include <cstdint>
+#include <limits>
 #include <map>
 #include <memory>
 #include <string>
@@ -223,6 +225,66 @@
 }
 } // namespace udt

+TEST_CASE("enum underlying types" * doctest::test_suite("udt"))
+{
+    SECTION("unsigned 64-bit enum")
+    {
+        enum class book_id : std::uint64_t {};
+        const std::vector<std::pair<std::uint64_t, std::string>> values =
+        {
+            {0, "0"},
+            {1, "1"},
+            {std::uint64_t(1) << 63, "9223372036854775808"},
+            {(std::numeric_limits<std::uint64_t>::max)() - 1, "18446744073709551614"},
+            {(std::numeric_limits<std::uint64_t>::max)(), "18446744073709551615"}
+        };
+
+        for (const auto& value : values)
+        {
+            const auto id = static_cast<book_id>(value.first);
+            const json j = id;
+            CHECK(j.is_number_unsigned());
+            CHECK(j.get<std::uint64_t>() == value.first);
+            CHECK(to_string(j) == value.second);
+            CHECK(j.get<book_id>() == id);
+            CHECK(json::parse(to_string(j)).get<book_id>() == id);
+            if (value.first != 0)
+            {
+                CHECK(j > 0u);
+            }
+
+            json assigned = "previous value";
+            assigned = id;
+            CHECK(assigned.is_number_unsigned());
+            CHECK(assigned == j);
+        }
+    }
+
+    SECTION("unsigned unscoped enum")
+    {
+        enum unsigned_enum : unsigned int { zero, one };
+        CHECK(json(zero).is_number_unsigned());
+        CHECK(json(one).is_number_unsigned());
+        CHECK(to_string(json(one)) == "1");
+    }
+
+    SECTION("signed enum")
+    {
+        enum class signed_enum : std::int64_t { negative = -1, zero, positive };
+        for (const auto value : {signed_enum::negative, signed_enum::zero, signed_enum::positive})
+        {
+            const json j = value;
+            CHECK(j.type() == json::value_t::number_integer);
+            CHECK(j.get<std::int64_t>() == static_cast<std::int64_t>(value));
+            CHECK(j.get<signed_enum>() == value);
+        }
+        CHECK(to_string(json(signed_enum::negative)) == "-1");
+    }
+}
+
 TEST_CASE("basic usage" * doctest::test_suite("udt"))
